select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-0000000000f2',false);
select 'finance: rates, entries, lines, payouts, history' t, (select count(*) from commission_rules), (select count(*) from commission_entries), (select count(*) from commission_lines), (select count(*) from commission_payouts), (select count(*) from commission_history);
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-0000000000e1',false);
select 'national reviewer: entries, payouts' t, (select count(*) from commission_entries), (select count(*) from commission_payouts);
